IF((SELECT @@SERVERNAME) = 'bzbdz2ikmp') BEGIN DECLARE @companyId int DECLARE @companyIDs table(companyId int) INSERT INTO @companyIDs VALUES (2),(13),(17),(23),(24),(35),(38),(39),(40),(46),(48),(49),(50),(52),(56),(57),(59), (60),(62),(64),(66),(70),(73),(86),(87),(89),(93),(94),(96),(97),(98),(100),(101), (102),(103),(109),(117),(118),(123),(126),(130),(131),(133),(137),(147),(149), (150),(153),(154),(155),(156),(157),(158),(159),(162),(163),(164),(166),(169), (172),(177),(178),(182),(183),(184),(197),(199),(204),(207),(208),(211),(216), (223),(225),(227),(228),(229),(230),(232),(240),(265);
DECLARE COMPANY_CURSOR CURSOR LOCAL STATIC READ_ONLY FORWARD_ONLY FOR SELECT DISTINCT CompanyId FROM @companyIDs
OPEN COMPANY_CURSOR FETCH NEXT FROM COMPANY_CURSOR INTO @companyId WHILE @@FETCH_STATUS = 0 BEGIN --Do something with Id here IF EXISTS (select 1 from company where id=@companyId) BEGIN IF EXISTS (SELECT 1 FROM CompanySetting WHERE CompanyID=@companyId AND SettingID=70) BEGIN UPDATE [dbo].[CompanySetting] SET Value = 'true' WHERE CompanyID=@companyId AND SettingID=70 END ELSE BEGIN INSERT INTO [dbo].[CompanySetting] VALUES (@companyId, 70, 'true') END END FETCH NEXT FROM COMPANY_CURSOR INTO @companyId END CLOSE COMPANY_CURSOR DEALLOCATE COMPANY_CURSOR END
